package in.lmt.inventory;
import in.lmt.shared.*;
import in.lmt.identity.ChallengeService;
import in.lmt.workspace.WorkspaceCommands;
import in.lmt.commercial.Entitlements;
import java.util.*;
import java.time.Instant;
import java.sql.*;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import tools.jackson.databind.ObjectMapper;
@Service @Transactional
public class AmenityCatalog {
 private final JdbcClient db;private final WorkspaceCommands scope;private final Entitlements entitlements;private final Audit audit;private final ObjectMapper json;
 public AmenityCatalog(JdbcClient db,WorkspaceCommands scope,Entitlements entitlements,Audit audit,ObjectMapper json){this.db=db;this.scope=scope;this.entitlements=entitlements;this.audit=audit;this.json=json;}
 public record Type(UUID id,String code,String name,String category,String description,String trackingMode,List<String> units,List<String> expectedDetails,List<String> aliases,String status,int version,String etag,Instant updatedAt){}
 public record Page(List<Type> items,List<String> categories,String nextCursor,long totalMatching,Instant asOf){}
 public record Revision(Type definition,Instant recordedAt){}
 public record Detail(Type definition,List<Revision> revisions){}
 private List<String> array(ResultSet r,String field)throws SQLException{return Arrays.asList((String[])r.getArray(field).getArray());}
 private Type type(ResultSet r)throws SQLException{UUID id=r.getObject("id",UUID.class);int v=r.getInt("version");return new Type(id,r.getString("code"),r.getString("name"),r.getString("category"),r.getString("description"),r.getString("tracking_mode"),array(r,"units"),array(r,"expected_details"),array(r,"aliases"),r.getString("status"),v,"\"amenity-"+id+"-v"+v+"\"",r.getTimestamp("updated_at").toInstant());}
 private Type find(UUID w,UUID id){return db.sql("SELECT * FROM amenity_type WHERE workspace_id=:w AND id=:id").param("w",w).param("id",id).query((r,n)->type(r)).optional().orElseThrow(()->new ApiProblem(404,"AMENITY_NOT_FOUND","Amenity definition is unavailable."));}
 private static String term(String value){return value.strip().toLowerCase(Locale.ROOT).replaceAll("\\s+","_");}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
 public Page list(UUID actor,UUID w,String search,String status,String category,String cursor){scope.requireOwner(w,actor);if(search==null)search="";if(category==null)category="";if(status==null)status="active";if(search.length()>120||category.length()>80||!Set.of("active","retired","all").contains(status))throw new ApiProblem(422,"INVALID_FILTER","Review catalog filters.","search");String q=term(search),binding=actor+":"+w+":"+ChallengeService.hash(q+":"+status+":"+category),after="";
  if(cursor!=null)try{var parts=new String(Base64.getUrlDecoder().decode(cursor),java.nio.charset.StandardCharsets.UTF_8).split("/");if(parts.length!=2||!parts[0].equals(binding)||!parts[1].matches("[A-Z][A-Z0-9_]{1,39}"))throw new IllegalArgumentException();after=parts[1];}catch(RuntimeException invalid){throw new ApiProblem(422,"INVALID_CURSOR","Reload the catalog after changing context or filters.","cursor");}
  String where="workspace_id=:w AND (:status='all' OR status=:status) AND (:category='' OR category=:category) AND (:q='' OR EXISTS(SELECT 1 FROM amenity_term t WHERE t.type_id=amenity_type.id AND t.workspace_id=:w AND position(:q in t.term)>0))";
  var rows=db.sql("SELECT * FROM amenity_type WHERE "+where+" AND code>:after ORDER BY code LIMIT 26").param("w",w).param("status",status).param("category",category).param("q",q).param("after",after).query((r,n)->type(r)).list();long total=db.sql("SELECT count(*) FROM amenity_type WHERE "+where).param("w",w).param("status",status).param("category",category).param("q",q).query(Long.class).single();var categories=db.sql("SELECT DISTINCT category FROM amenity_type WHERE workspace_id=:w ORDER BY category").param("w",w).query(String.class).list();boolean more=rows.size()>25;var items=more?rows.subList(0,25):rows;String next=more?Base64.getUrlEncoder().withoutPadding().encodeToString((binding+"/"+items.getLast().code()).getBytes(java.nio.charset.StandardCharsets.UTF_8)):null;return new Page(items,categories,next,total,Instant.now());
 }
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
 public Detail detail(UUID actor,UUID w,UUID id){scope.requireOwner(w,actor);Type current=find(w,id);var revisions=db.sql("SELECT a.*,v.recorded_at FROM amenity_type_version v CROSS JOIN LATERAL jsonb_populate_record(NULL::amenity_type,v.snapshot) a WHERE v.workspace_id=:w AND v.type_id=:id ORDER BY v.version DESC LIMIT 50").param("w",w).param("id",id).query((r,n)->new Revision(type(r),r.getTimestamp("recorded_at").toInstant())).list();return new Detail(current,revisions);}
 public Type save(UUID actor,UUID w,UUID id,UUID key,String expected,AmenityController.Input input){scope.requireOwner(w,actor);db.sql("SELECT pg_advisory_xact_lock(hashtextextended(:k,0))").param("k","membership:"+w).query().singleRow();db.sql("SELECT pg_advisory_xact_lock(hashtextextended(:k,0))").param("k","amenity:"+w).query().singleRow();scope.requireOwner(w,actor);entitlements.require(w,"PROPERTY_EDIT");String hash=ChallengeService.hash(json.writeValueAsString(Arrays.asList(id,expected,input)));
  var prior=db.sql("SELECT request_hash,result::text FROM amenity_command WHERE workspace_id=:w AND actor_id=:a AND request_key=:k").param("w",w).param("a",actor).param("k",key).query().listOfRows();if(!prior.isEmpty()){if(!prior.getFirst().get("request_hash").equals(hash))throw new ApiProblem(409,"IDEMPOTENCY_CONFLICT","This key belongs to another catalog confirmation.");return json.readValue((String)prior.getFirst().get("result"),Type.class);}
  int version=1;if(id!=null){var current=find(w,id);if(expected==null||expected.isBlank())throw new ApiProblem(428,"PRECONDITION_REQUIRED","Refresh and review the current definition.");if(!expected.equals(current.etag()))throw new ApiProblem(412,"VERSION_STALE","The definition changed. Reload and review again.");if(!input.code().equals(current.code()))throw new ApiProblem(422,"CODE_IMMUTABLE","Stable catalog codes cannot be changed.","code");version=current.version()+1;}else{id=UUID.randomUUID();if(!input.status().equals("active"))throw new ApiProblem(422,"INITIAL_STATUS_INVALID","Create an active definition before retiring it.","status");}
  if(!Set.of("serialized","quantity","feature","service").contains(input.trackingMode())||!Set.of("active","retired").contains(input.status()))throw new ApiProblem(422,"INVALID_DEFINITION","Choose a supported tracking mode and status.","trackingMode");
  if(Set.of("feature","service").contains(input.trackingMode())&&!input.units().equals(List.of("availability")))throw new ApiProblem(422,"INVALID_UNIT_OF_MEASURE","Features/services use availability, not physical quantities.","units");
  var terms=new LinkedHashSet<String>();terms.add(term(input.code()));terms.add(term(input.name()));input.aliases().forEach(a->terms.add(term(a)));for(String value:terms){String field=value.equals(term(input.code()))?"code":value.equals(term(input.name()))?"name":"aliases";if(value.length()>120)throw new ApiProblem(422,"ALIAS_TOO_LONG","Normalized names and aliases must fit 120 characters.",field);if(value.isEmpty())throw new ApiProblem(422,"EMPTY_ALIAS","Aliases and names must contain text.",field);if(db.sql("SELECT EXISTS(SELECT 1 FROM amenity_term WHERE workspace_id=:w AND term=:term AND type_id<>:id)").param("w",w).param("term",value).param("id",id).query(Boolean.class).single())throw new ApiProblem(409,"CATALOG_TERM_EXISTS","A code, name or alias already identifies another item. Use that existing definition.",field);}
  String category=db.sql("SELECT category FROM amenity_type WHERE workspace_id=:w AND lower(category)=lower(:c) ORDER BY code LIMIT 1").param("w",w).param("c",input.category().strip()).query(String.class).optional().orElse(input.category().strip());
  // JSON-to-array conversion keeps values parameterized, without interpolating SQL or array literals.
  db.sql("INSERT INTO amenity_type(id,workspace_id,code,name,category,description,tracking_mode,units,expected_details,aliases,status,version) VALUES(:id,:w,:code,:name,:category,:description,:mode,ARRAY(SELECT jsonb_array_elements_text(CAST(:units AS jsonb))),ARRAY(SELECT jsonb_array_elements_text(CAST(:details AS jsonb))),ARRAY(SELECT jsonb_array_elements_text(CAST(:aliases AS jsonb))),:status,:version) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category=excluded.category,description=excluded.description,tracking_mode=excluded.tracking_mode,units=excluded.units,expected_details=excluded.expected_details,aliases=excluded.aliases,status=excluded.status,version=excluded.version,updated_at=clock_timestamp()")
   .param("id",id).param("w",w).param("code",input.code()).param("name",input.name().strip()).param("category",category).param("description",input.description().strip()).param("mode",input.trackingMode()).param("units",json.writeValueAsString(input.units())).param("details",json.writeValueAsString(input.expectedDetails())).param("aliases",json.writeValueAsString(input.aliases())).param("status",input.status()).param("version",version).update();
  // Retain every historical spelling reservation so aliases cannot later identify another physical type.
  for(String value:terms)db.sql("INSERT INTO amenity_term(workspace_id,type_id,term) VALUES(:w,:id,:term) ON CONFLICT DO NOTHING").param("w",w).param("id",id).param("term",value).update();
  db.sql("INSERT INTO amenity_type_version(workspace_id,type_id,version,snapshot,actor_id) SELECT workspace_id,id,version,to_jsonb(a)-'workspace_id',:actor FROM amenity_type a WHERE id=:id").param("actor",actor).param("id",id).update();Type result=find(w,id);audit.record(actor,w,"inventory.catalog_definition_saved",id);db.sql("INSERT INTO amenity_command(workspace_id,actor_id,request_key,request_hash,result) VALUES(:w,:a,:k,:h,CAST(:r AS jsonb))").param("w",w).param("a",actor).param("k",key).param("h",hash).param("r",json.writeValueAsString(result)).update();return result;
 }
}
